1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  cursed?: boolean;
8	  enchantment?: number;
9	}
10	
11	const PROCESSING_FEE = 5;
12	const CURSE_SURCHARGE_RATE = 0.5;
13	const HIGH_ENCHANTMENT_LEVEL = 5;
14	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
15	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
16	
17	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
18	  sword: 100,
19	  amulet: 60,
20	  staff: 80,
21	  potion: 40,
22	};
23	
24	const COMPONENT_TYPES = ["rune", "moonstone"];
25	const COMPONENT_BASE_PREMIUM = 25;
26	const BLOCK_SIZE = 3;
27	const BLOCK_BASE_PREMIUM = 60;
28	
29	function isComponent(item: Item): boolean {
30	  return COMPONENT_TYPES.includes(item.type);
31	}
32	
33	function countsPerAlikeGroup(components: Item[]): number[] {
34	  const counts = new Map<string, number>();
35	  for (const component of components) {
36	    counts.set(component.type, (counts.get(component.type) ?? 0) + 1);
37	  }
38	  return [...counts.values()];
39	}
40	
41	function alikeComponentsBasePremiumOf(count: number): number {
42	  return count === BLOCK_SIZE
43	    ? BLOCK_BASE_PREMIUM
44	    : count * COMPONENT_BASE_PREMIUM;
45	}
46	
47	function componentsBasePremiumOf(components: Item[]): number {
48	  return countsPerAlikeGroup(components).reduce(
49	    (total, count) => total + alikeComponentsBasePremiumOf(count),
50	    0,
51	  );
52	}
53	
54	function basePremiumOf(item: Item): number {
55	  return isComponent(item)
56	    ? COMPONENT_BASE_PREMIUM
57	    : MAIN_ITEM_BASE_PREMIUMS[item.type];
58	}
59	
60	function mainItemsBasePremiumOf(mainItems: Item[]): number {
61	  return mainItems.reduce((total, item) => total + basePremiumOf(item), 0);
62	}
63	
64	function policyBasePremiumOf(items: Item[]): number {
65	  return (
66	    mainItemsBasePremiumOf(items.filter((item) => !isComponent(item))) +
67	    componentsBasePremiumOf(items.filter(isComponent))
68	  );
69	}
70	
71	function isCursed(item: Item): boolean {
72	  return item.cursed === true;
73	}
74	
75	function isHighlyEnchanted(item: Item): boolean {
76	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
77	}
78	
79	function riskSurchargeRateOf(item: Item): number {
80	  return (
81	    (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
82	    (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0)
83	  );
84	}
85	
86	function itemSpecificSurchargesOf(items: Item[]): number {
87	  return items.reduce(
88	    (total, item) => total + basePremiumOf(item) * riskSurchargeRateOf(item),
89	    0,
90	  );
91	}
92	
93	function roundPremiumInMHPCOsFavour(amount: number): number {
94	  return Math.ceil(amount);
95	}
96	
97	function firstInsuranceSurchargeOf(policyBasePremium: number): number {
98	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
99	}
100	
101	export function quote(
102	  customer: Customer,
103	  items: Item[],
104	  previousQuoteCount: number,
105	): number {
106	  const policyBasePremium = policyBasePremiumOf(items);
107	  const premiumBeforeFee =
108	    policyBasePremium +
109	    itemSpecificSurchargesOf(items) +
110	    firstInsuranceSurchargeOf(policyBasePremium);
111	  return roundPremiumInMHPCOsFavour(premiumBeforeFee + PROCESSING_FEE);
112	}
