function mainItemBasePremiumOf(item: Item): number {
  return MAIN_ITEM_BASE_PREMIUMS[item.type];
}

function mainItemsBasePremiumOf(mainItems: Item[]): number {
  return mainItems.reduce(
    (total, item) => total + mainItemBasePremiumOf(item),
    0,
  );
}

// Item-specific modifiers apply to the affected item's own base premium,
// so a component is surcharged on its single-component rate rather than on
// its share of a discounted building block.
function surchargeableBasePremiumOf(item: Item): number {
  return isComponent(item)
    ? COMPONENT_BASE_PREMIUM
    : mainItemBasePremiumOf(item);
}

function policyBasePremiumOf(items: Item[]): number {
  return (
    mainItemsBasePremiumOf(items.filter((item) => !isComponent(item))) +
    componentsBasePremiumOf(items.filter(isComponent))
  );
}

function isCursed(item: Item): boolean {
  return item.cursed === true;
}

function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
}

function riskSurchargeRateOf(item: Item): number {
  return (
    (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
    (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0)
  );
}

function itemRiskSurchargesOf(items: Item[]): number {
  return items.reduce(
    (total, item) => total + surchargeableBasePremiumOf(item) * riskSurchargeRateOf(item),
    0,
  );
}

function roundPremiumInMHPCOsFavour(amount: number): number {
  return Math.ceil(amount);
}
